%[text] ## Portfolio Optimization Engine
%[text] For this project I will be using hypothetical simulated daily returns and averages
%[text] The code assumes a 1.5% daily standard deviation and a 0.05% average daily return
%[text] For this simulation It's running 15,000 randomly generated portfolios
%%
clc;
clear;
close all;

% Portfolio stocks
stocks = ["AAPL", "MSFT", "NVDA", "AMZN", "GOOGL"];

n = length(stocks);

days = 252;

rng(42);

dailyReturns = randn(days,n)*0.015 + 0.0005;

disp("Sample Daily Returns:"); %[output:2aeb15cd]
disp(array2table(dailyReturns, ... %[output:group:7048f05d] %[output:182c3957]
    'VariableNames', cellstr(stocks))); %[output:group:7048f05d] %[output:182c3957]
%%
meanDailyReturns = mean(dailyReturns);

% annualize expected returns
annualReturns = meanDailyReturns * 252;

disp("Expected Annual Returns:"); %[output:3a7a6ab8]

disp(array2table(annualReturns, ... %[output:group:313f2aaf] %[output:7b242466]
    'VariableNames', cellstr(stocks))); %[output:group:313f2aaf] %[output:7b242466]

%%
dailyCovariance = cov(dailyReturns);

% Annualized covariance matrix
annualCovariance = dailyCovariance * 252;

disp("Annual Covariance Matrix:"); %[output:1b206fe7]

disp(array2table(annualCovariance, ... %[output:group:1ca30ff6] %[output:712d712d]
    'VariableNames', cellstr(stocks), ... %[output:712d712d]
    'RowNames', cellstr(stocks))); %[output:group:1ca30ff6] %[output:712d712d]
%%
%[text] Portfolio risk was calculated using the portfolio standard deviation formula

weights = ones(n,1)/n;

portfolioReturn = weights' * annualReturns';

% Calculate portfolio risk
portfolioRisk = sqrt(weights' * ...
    annualCovariance * weights);

disp("Portfolio Annual Return:"); %[output:9d01e992]
disp(portfolioReturn); %[output:7c5669ed]

disp("Portfolio Annual Risk:"); %[output:685e08e9]
disp(portfolioRisk); %[output:12e51ad5]
%%
%[text] Using the softmax transformation prior to the optimization to weight the portfolios
%[text] Unfortunately this method wont permit exact zero allocations, also MATLAB's fminsearch function only guarantees local(not global) optimum
%[text] Set to 10,000 optimization iterations and 50,000 function evaluations
%[text] Basically pushing the limit
%[text] Removed the largest value from each logit to minimize noise later


% initial equal allocation
z0 = zeros(n-1,1);


options = optimset('Display','iter', ...
    'MaxIter',10000, ...
    'MaxFunEvals',50000);

% run optimization
zOptimal = fminsearch(@(z) portfolioObjective(z, annualCovariance), ... %[output:group:89f3fe86] %[output:2916c9a4]
    z0, options); %[output:group:89f3fe86] %[output:2916c9a4]

% convert optimized variables into portfolio weights
logits = [zOptimal(:); 0];
logits = logits - max(logits);

optimalWeights = exp(logits) / sum(exp(logits));

% calculate minimum portfolio variance
minimumVariance = optimalWeights' * annualCovariance * optimalWeights;

disp("Optimal Stock Allocations:"); %[output:0a6cb1d4]

disp(array2table(optimalWeights', ... %[output:group:36e877b9] %[output:0fcc51a7]
    'VariableNames', matlab.lang.makeValidName(cellstr(stocks)))); %[output:group:36e877b9] %[output:0fcc51a7]

fprintf('Minimum Portfolio Variance: %.8f\n', minimumVariance); %[output:1a43ead7]

% objective function
function variance = portfolioObjective(z, annualCovariance)

logits = [z(:); 0];
logits = logits - max(logits);

w = exp(logits) / sum(exp(logits));

variance = w' * annualCovariance * w;

end
%%
%[text] Risk free rate is set to a hypothetical 4%
%%
% Calculate optimized portfolio return
optimalReturn = optimalWeights' * annualReturns';

% calculate optimized portfolio risk
optimalRisk = sqrt(optimalWeights' * ...
    annualCovariance * optimalWeights);

% calculate Sharpe ratio
riskFreeRate = 0.04;

sharpeRatio = (optimalReturn-riskFreeRate) ...
    / optimalRisk;

disp("OPTIMIZED PORTFOLIO RESULTS"); %[output:46d361f8]

fprintf("Expected Annual Return: %.2f%%\n", ... %[output:group:2ddde8e7] %[output:756d40b2]
    optimalReturn*100); %[output:group:2ddde8e7] %[output:756d40b2]

fprintf("Annual Risk: %.2f%%\n", ... %[output:group:30007647] %[output:251d842b]
    optimalRisk*100); %[output:group:30007647] %[output:251d842b]

fprintf("Sharpe Ratio: %.4f\n", sharpeRatio); %[output:868e10a7]
%%
clc;


numPortfolios = 15000;
riskFreeRate = 0.04;

rng(42);

%%\ 2. GENERATE RANDOM PORTFOLIOS

randomWeights = rand(numPortfolios,n);

% Normalize weights to total 100%
randomWeights = randomWeights ./ sum(randomWeights,2);

% Calculate portfolio returns
simulatedReturns = randomWeights * annualReturns';

% Calculate portfolio risks
simulatedRisks = sqrt(sum( ...
    (randomWeights * annualCovariance) .* ...
    randomWeights,2));

% Calculate sharpe ratios
simulatedSharpe = ...
    (simulatedReturns-riskFreeRate) ./ simulatedRisks;


% Select the best portfolio from the simulation

[~,bestIndex] = max(simulatedSharpe);

tangencyWeights = randomWeights(bestIndex,:)';

tangencyReturn = simulatedReturns(bestIndex);

tangencyRisk = simulatedRisks(bestIndex);

tangencySharpe = simulatedSharpe(bestIndex);

% INDIVIDUAL STOCK STATISTICS

stockReturns = annualReturns';

stockRisks = sqrt(diag(annualCovariance));

%%\ CAPITAL MARKET LINE

cmlRisk = linspace(0,max(simulatedRisks)*1.1,100);

cmlReturn = riskFreeRate + tangencySharpe*cmlRisk;

%%\ CREATE FIGURE

figure('Color','w','Position',[100 100 1200 750]); %[output:7787743c]

hold on; %[output:7787743c]
grid on; %[output:7787743c]
box on; %[output:7787743c]

%%\ MONTE CARLO PORTFOLIO CLOUD

scatter(simulatedRisks*100, ... %[output:7787743c]
    simulatedReturns*100, ... %[output:7787743c]
    12, simulatedSharpe, 'filled'); %[output:7787743c]

colormap(jet); %[output:7787743c]

cb = colorbar; %[output:7787743c]
ylabel(cb,'Sharpe Ratio'); %[output:7787743c]

%%\ EFFICIENT FRONTIER

plot(frontierRisk*100, ... %[output:7787743c]
    targetReturns*100, ... %[output:7787743c]
    'r-', 'LineWidth',3); %[output:7787743c]

%%\ MINIMUM VARIANCE PORTFOLIO

minReturn = optimalWeights' * annualReturns';

minRisk = sqrt( ...
    optimalWeights' * annualCovariance * optimalWeights);

plot(minRisk*100, ... %[output:7787743c]
    minReturn*100, ... %[output:7787743c]
    'b*', 'MarkerSize',18, 'LineWidth',2); %[output:7787743c]

%%\ TANGENCY PORTFOLIO

plot(tangencyRisk*100, ... %[output:7787743c]
    tangencyReturn*100, ... %[output:7787743c]
    'p', 'MarkerSize',18, ... %[output:7787743c]
    'MarkerFaceColor','y', ... %[output:7787743c]
    'MarkerEdgeColor','k'); %[output:7787743c]

%%\ CAPITAL MARKET LINE

plot(cmlRisk*100, ... %[output:7787743c]
    cmlReturn*100, ... %[output:7787743c]
    'k--', 'LineWidth',1.8); %[output:7787743c]

%%\ INDIVIDUAL STOCKS

plot(stockRisks*100, ... %[output:7787743c]
    stockReturns*100, ... %[output:7787743c]
    ['d'], ... %[output:7787743c]
    'MarkerSize',10, ... %[output:7787743c]
    'MarkerFaceColor','w', ... %[output:7787743c]
    'MarkerEdgeColor','r', ... %[output:7787743c]
    'LineWidth',1.8); %[output:7787743c]

%%\ LABEL STOCKS

for i = 1:n

    text(stockRisks(i)*100+0.3, ... %[output:7787743c]
        stockReturns(i)*100, ... %[output:7787743c]
        char(stocks(i)), ... %[output:7787743c]
        'FontSize',10, ... %[output:7787743c]
        'FontWeight','bold',... %[output:7787743c]
        'Color',[0 0 0]); %[output:7787743c]

end



xlabel('Annual Portfolio Risk (%)', ... %[output:7787743c]
     'Color',[0 0 0], ... %[output:7787743c]
    'FontSize',13); %[output:7787743c]

ylabel('Annual Expected Return (%)', ... %[output:7787743c]
     'Color',[0 0 0], ... %[output:7787743c]
    'FontSize',13); %[output:7787743c]

title('Efficient Frontier with Capital Market Line', ... %[output:7787743c]
     'Color',[0 0 0], ... %[output:7787743c]
    'FontSize',16); %[output:7787743c]

legend('Simulated Portfolios', ... %[output:7787743c]
    'Efficient Frontier', ... %[output:7787743c]
    'Minimum Variance', ... %[output:7787743c]
    'Tangency (Max Sharpe)', ... %[output:7787743c]
    'Capital Market Line', ... %[output:7787743c]
    'Individual Stocks', ... %[output:7787743c]
    'Location','northoutside',... %[output:7787743c]
    'Color',[1 1 1], ... %[output:7787743c]
    'TextColor',[0 0 0]); %[output:7787743c]

cb = colorbar; %[output:7787743c]
set(cb,'Color',[0 0 0]); %[output:7787743c]
ylabel(cb,'Sharpe Ratio','Color',[0 0 0]); %[output:7787743c]

set(gca,'XColor',[0 0 0], ... %[output:7787743c]
    'YColor',[0 0 0]); %[output:7787743c]

set(gca,'Color',[1 1 1]); %[output:7787743c]

set(gca,'GridColor',[0 0 0], ... %[output:7787743c]
    'GridAlpha',0.3); %[output:7787743c]

set(gca,'FontSize',11) %[output:7787743c]
hold off; %[output:7787743c]

%%\ DISPLAY RESULTS

fprintf('\nPORTFOLIO OPTIMIZATION RESULTS\n'); %[output:09ff01e8]

fprintf('Minimum Variance Risk: %.2f%%\n',minRisk*100); %[output:4d562e61]

fprintf('Minimum Variance Return: %.2f%%\n',minReturn*100); %[output:408c9a67]

fprintf('Tangency Portfolio Risk: %.2f%%\n',tangencyRisk*100); %[output:73daf70a]

fprintf('Tangency Portfolio Return: %.2f%%\n',tangencyReturn*100); %[output:3ab021bb]

fprintf('Tangency Sharpe Ratio: %.4f\n',tangencySharpe); %[output:28171c2d]

